/* EstateMaster API option. EstateMaster is reached through an API (simulated in this demo: calls are logged with their
   request and response, and the responses come from the demo's stand-in for EstateMaster, the same one behind
   "simulated export" in Option 2). The agent reads through the API at any time; it writes only an approved change
   request (PATCH inputs → POST calculate → GET outputs), so nothing reaches EstateMaster before a person approves it. */
const EMAPI={base:'https://estatemaster.kinan.sa/api/v1',log:[],n:1,busy:{}};
const apiModel=(proj=PROJ.id)=>`/models/${proj}`;
const apiWait=ms=>new Promise(r=>setTimeout(r,ms));
function apiInputs(){return REG.filter(l=>!l.comp||l.comp==='all'||(PROJ.comps||[]).includes(l.comp)).map(l=>{let v=NaN;try{v=lineVal(l.id)}catch(e){}return Number.isFinite(v)?{label:l.label,value:v,text:fmtLine(l,v),unit:l.unit,section:l.g,sheet:'API'}:null}).filter(Boolean)}
async function apiCall(method,path,req,res,ms){ms=ms||Math.round(220+Math.random()*520);const t0=new Date().toISOString();await apiWait(ms);
  const body=typeof res==='function'?res():res,e={id:EMAPI.n++,at:t0,method,path,status:method==='POST'&&/\/models$/.test(path)?201:200,ms,req:req||null,res:body};
  EMAPI.log.unshift(e);if(EMAPI.log.length>80)EMAPI.log.length=80;renderApiLog();return e}
async function apiRun(id){const t=TASKS.find(x=>x.id===id);if(!t||t.status!=='open'||EMAPI.busy[id])return;
  if(t.proj!==PROJ.id){toast(`${t.id} belongs to ${PROJECTS[t.proj]?PROJECTS[t.proj].name:'another project'}: switch project first`);return}
  EMAPI.busy[id]=true;renderEMTab();renderApprovals();const m=apiModel(t.proj),crs=t.crs.map(c=>APQ.find(x=>x.id===c)).filter(Boolean),ids=crs.map(c=>c.id);
  const strip=v=>String(v).replace(/<[^>]+>/g,'');
  try{
    if(t.kind==='stress'){
      await apiCall('POST',`${m}/sandbox`,{from:'live',reason:t.id},{sandbox:`${t.proj}-sbx-${t.id}`,copyOf:'live'});
      await apiCall('POST',`${m}/sandbox/scenarios`,{scenarios:t.scen.map(g=>({id:g.id,name:g.name}))},{accepted:t.scen.length,status:'calculated'},900);
      if(t.proj!==PROJ.id)throw new Error('project switched');
      await completeTask(t.id,null,{api:true});
      await apiCall('GET',`${m}/sandbox/results`,null,()=>({results:t.scen.map(g=>({id:g.id,levered_irr:GEN.em[g.id]&&GEN.em[g.id].irr})),liveModelChanged:false}))}
    else{
      if(t.kind==='newmodel'){const d=crs[0]&&crs[0].def;await apiCall('POST','/models',{name:d&&d.name,template:d&&TEMPLATES[d.template].name,changeRequest:ids[0]},{id:t.proj,status:'created'})}
      const changes=crs.flatMap(c=>(c.rows||[]).map(r=>({changeRequest:c.id,input:strip(r[0]),from:strip(r[1]),to:strip(r[2])})));
      await apiCall('PATCH',`${m}/inputs`,{changeRequests:ids,approvedBy:[...new Set(crs.map(c=>c.decidedBy).filter(Boolean))],changes},{accepted:changes.length||ids.length,status:'pending recalculation'});
      await apiCall('POST',`${m}/calculate`,{},{status:'completed',engine:'ARGUS EstateMaster'},1100);
      if(t.proj!==PROJ.id)throw new Error('project switched');
      await completeTask(t.id,null,{api:true});
      const x=latestExport(t.proj);await apiCall('GET',`${m}/outputs`,null,{version:x&&x.id,outputs:x&&x.out})}
    logEvent({kind:'export',actor:'EstateMaster API (simulated)',channel:'EstateMaster API',detail:`${t.id}: ${t.kind==='stress'?'stress scenarios run on a sandbox copy':'approved change written'} through the API${ids.length?' ('+ids.join(', ')+')':''}; EstateMaster recalculated and its figures were read back`,cr:ids[0]})}
  catch(e){toast(`${t.id}: the EstateMaster API call stopped (${e.message}). Press “Run through the API” to retry.`)}
  finally{delete EMAPI.busy[id];renderEMTab();renderApprovals();renderApiLog();saveMem()}}
async function apiSync(quiet){const m=apiModel(),btn=$('#apiSync');if(btn){btn.disabled=true;btn.textContent='Syncing…'}
  try{await apiCall('GET','/models',null,{models:Object.values(PROJECTS).map(p=>({id:p.id,name:p.name}))});
    const out=simOut(),x=latestExport(),same=x&&EXROWS.every(([k])=>!Number.isFinite(out[k])||Math.abs((x.out[k]??NaN)-out[k])<1e-6);
    await apiCall('GET',`${m}/outputs`,null,{version:same?x.id:'new',outputs:out});
    if(!same){addExport('api','read through the EstateMaster API (sync)',out,'','',{inputs:apiInputs()});renderAll(true)}
    else if(x&&!(x.inputs||[]).length){await apiCall('GET',`${m}/inputs`,null,()=>({inputs:apiInputs().length}));x.inputs=apiInputs()}
    if(!quiet)toast(same?'EstateMaster API: up to date':'EstateMaster API: new figures read');EMAPI.last=new Date().toISOString()}
  finally{if(btn){btn.disabled=false;btn.textContent='Sync now'}renderApiLog();renderEMTab();saveMem()}}
function renderApiLog(){const el=$('#apiLog');if(!el)return;const x=latestExport();
  $('#apiSub').innerHTML=`<b>Connected (simulated)</b> · ${esc(EMAPI.base)} · model <b>${esc(apiModel())}</b>${x?` · latest figures ${esc(x.id)}`:''}. Reads at any time; writes only an approved change request, then EstateMaster recalculates and the figures are read back.`;
  el.innerHTML=EMAPI.log.length?'<tr><th>When</th><th>Call</th><th class="n">Status</th><th class="n">ms</th></tr>'+EMAPI.log.slice(0,40).map(e=>`<tr data-apil="${e.id}" style="cursor:pointer"><td style="font-size:12px;white-space:nowrap">${new Date(e.at).toLocaleTimeString('en-GB')}</td><td style="font-size:12px"><b>${e.method}</b> <code>${esc(e.path)}</code></td><td class="n">${e.status}</td><td class="n">${e.ms}</td></tr>`+(EMAPI.open===e.id?`<tr><td colspan="4"><pre style="white-space:pre-wrap;font-size:11.5px;margin:0;max-height:260px;overflow:auto">${e.req?'Request\n'+esc(JSON.stringify(e.req,null,2))+'\n\n':''}Response\n${esc(JSON.stringify(e.res,null,2))}</pre></td></tr>`:'')).join(''):'<tr><td class="sub">No calls yet.</td></tr>'}
/* wording: the shared Option 2 copy speaks of analysts and exports; in this option the API does that step */
const AXR=[[/I never write to EstateMaster: an analyst applies approved changes\./g,'I write to EstateMaster only through its API, after a person approves.'],
 [/an analyst can run (it|the change|this case|any cell) in EstateMaster for its own/g,'once approved, the agent runs $1 in EstateMaster through the API for its own'],
 [/Ask an analyst to run the scenario in EstateMaster for its own figure/g,'Approve it and the agent runs it in EstateMaster through the API for its own figure'],
 [/say an analyst can run it in EstateMaster/g,'say EstateMaster can run it through the API once a person approves'],
 [/until an analyst runs the change in EstateMaster/g,'until EstateMaster has run the change through the API (after approval)'],
 [/EstateMaster’s own (figure|IRR) comes once an analyst applies (it|the change)/g,'EstateMaster’s own $1 comes back through the API once the change is approved'],
 [/calculated by EstateMaster once an analyst applies it/g,'calculated by EstateMaster once approved (through the API)'],
 [/once approved, an analyst enters (it|them) in EstateMaster and uploads (the|a) new export/g,'once approved, the agent writes $1 to EstateMaster through the API and reads back EstateMaster’s recalculated figures'],
 [/after an analyst enters it/g,'after a person approves it and the agent writes it through the API'],
 [/an analyst enters it in EstateMaster and uploads the new export; the figures update then/g,'the agent writes it to EstateMaster through the API and reads the recalculated figures back'],
 [/EstateMaster changes only after a person approves and an analyst applies them/g,'EstateMaster changes only after a person approves them; the agent then writes them through the API'],
 [/Approved changes are applied in EstateMaster by an analyst/g,'Approved changes are written to EstateMaster through the API'],
 [/an analyst runs each on a copy of the model and uploads the export/g,'EstateMaster runs each on a sandbox copy through the API'],
 [/EstateMaster’s figures appear once an analyst runs them/g,'EstateMaster’s figures appear once it runs them through the API'],
 [/hand a scenario to an analyst for EstateMaster’s figure/g,'run a scenario in EstateMaster through the API for its figure'],
 [/to create the analyst task/g,'to run them through the API'],[/Hand the 5 worst to an analyst/g,'Run the 5 worst in EstateMaster (API)'],
 [/handed to an analyst to run in EstateMaster on a copy/g,'sent to EstateMaster through the API to run on a sandbox copy'],
 [/scenarios for an analyst to run in EstateMaster/g,'scenarios running in EstateMaster through the API'],
 [/and an analyst to run in EstateMaster/g,'and EstateMaster to run through the API'],
 [/an analyst copies/g,'the agent, through the API, copies'],[/an analyst applies approved changes/g,'approved changes are written through the EstateMaster API'],
 [/an analyst enters it in EstateMaster/g,'the agent writes it to EstateMaster through the API'],[/an analyst enters it\./g,'the agent writes it through the API.'],
 [/For the analyst · approved changes to apply in EstateMaster/g,'EstateMaster API · approved changes written'],[/listed under “For the analyst” below/g,'each call is in the API log on the Financial model tab'],
 [/approved changes are entered by an analyst/g,'approved changes are written through the EstateMaster API'],[/applied by an analyst/g,'written through the EstateMaster API'],
 [/waiting for an analyst/g,'waiting for the EstateMaster API'],[/[Tt]ask (T-\d+) for an analyst/g,'API job $1'],[/for an analyst/g,'via the EstateMaster API'],
 [/(\d+) analyst tasks? open: approved changes not yet in EstateMaster/g,'$1 API job(s) running: approved changes not yet in EstateMaster'],[/analyst task/g,'API job'],
 [/figures update once the new export is read/g,'figures update once EstateMaster returns them'],[/\(simulated export\)/g,'(simulated API)'],
 [/upload one on the EstateMaster tab/g,'press Sync now on the Financial model tab'],[/The agent never runs or writes to EstateMaster\./g,'The agent writes to EstateMaster only through its API, after a person approves.'],
 [/every figure shown as EstateMaster’s comes from its own export/g,'every figure shown as EstateMaster’s is read from EstateMaster through its API'],
 [/This model’s EstateMaster exports, every assumption read from them, the checks on the latest export and the comparison between exports\. The latest export is the only source of the figures shown as EstateMaster’s\./g,'The EstateMaster API and its call log, every version of the model read through it, every assumption, the checks on the latest version and the comparison between versions. The latest API read is the only source of the figures shown as EstateMaster’s.'],
 [/All figures from EstateMaster’s exports \(simulated exports in this demo\)/g,'All figures read from EstateMaster through its API (simulated in this demo)']];
function ax(s){if(MODE!=='api'||typeof s!=='string')return s;for(const[a,b]of AXR)s=s.replace(a,b);return s}
function axNode(n){if(n.nodeType===3){if(/analyst|export/i.test(n.nodeValue)){const v=ax(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v}return}
  if(n.nodeType!==1||n.tagName==='SCRIPT'||n.tagName==='STYLE'||n.tagName==='TEXTAREA'||n.tagName==='INPUT')return;
  const w=document.createTreeWalker(n,NodeFilter.SHOW_TEXT);let t;while((t=w.nextNode()))axNode(t)}
function apiInit(){
  const em=$('#p-em .grid > div');if(em&&!$('#apiCard'))em.insertAdjacentHTML('afterbegin',`<div class="card" id="apiCard"><div class="bar"></div><div class="sbhead"><h2>EstateMaster API</h2><span class="pill s">simulated</span><button class="btn sm" id="apiSync" style="margin-left:auto">Sync now</button></div><div class="sub" id="apiSub"></div><div class="sub" style="margin:6px 0 0;font-size:12px">Click a call for its request and response.</div><div class="scroll" style="max-height:340px;overflow:auto"><table class="t" id="apiLog"></table></div></div>`);
  const h=$('#exUp')&&$('#exUp').closest('.card').querySelector('h2');if(h)h.textContent='EstateMaster versions';
  document.addEventListener('click',e=>{const a=e.target.closest('[data-tapi]'),l=e.target.closest('[data-apil]');if(a)apiRun(a.dataset.tapi);if(e.target.id==='apiSync')apiSync(false);if(l){const id=+l.dataset.apil;EMAPI.open=EMAPI.open===id?null:id;renderApiLog()}});
  axNode(document.body);document.title=document.title;
  new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')axNode(m.target);else m.addedNodes.forEach(axNode)}}).observe(document.body,{childList:true,subtree:true,characterData:true});
  renderApiLog()}

