  if(t.kind==='newmodel')return[`POST /models: new model from the KINAN ${crs[0]&&crs[0].def?TEMPLATES[crs[0].def.template].name:''} template`,`PATCH ${m}/inputs: the approved values`,`POST ${m}/calculate`,`GET ${m}/outputs: EstateMaster’s figures`];
  return[`PATCH ${m}/inputs: ${crs.reduce((n,c)=>n+(c.rows||[]).length,0)||crs.length} approved value${crs.length>1?'s':''} (${crs.map(c=>c.id).join(', ')})`,`POST ${m}/calculate: EstateMaster recalculates`,`GET ${m}/outputs: EstateMaster’s recalculated figures read back`]}
